package com.hbm.client.entity.maskman;
import com.hbm.client.model.*;import com.hbm.entity.mob.maskman.LegacyNpcBullets;import com.hbm.entity.projectile.EntityBulletBaseNT;import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import java.util.Random;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.texture.OverlayTexture;import net.minecraft.client.renderer.entity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.Vec3;
/** Original RenderBullet's actually enabled styles: orb1, bolt0/1/2/4, rocket0 and meteor0. Exact source meshes and coloured bolt triangles. */
public final class NpcBulletRenderer extends EntityRenderer<EntityBulletBaseNT>{public NpcBulletRenderer(EntityRendererProvider.Context context){super(context);}@Override public ResourceLocation getTextureLocation(EntityBulletBaseNT e){return ResourceLocation.parse("hbm:textures/models/projectiles/rocket.png");}
 @Override public void render(EntityBulletBaseNT e,float yaw,float partial,PoseStack p,MultiBufferSource buffers,int light){var cfg=e.config();if(cfg==null)return;p.pushPose();p.mulPose(Axis.YP.rotationDegrees(e.yRotO+(e.getYRot()-e.yRotO)*partial-90));p.mulPose(Axis.ZP.rotationDegrees(e.xRotO+(e.getXRot()-e.xRotO)*partial+180));p.scale(1.5F,1.5F,1.5F);if(cfg.style!=15)p.mulPose(Axis.XP.rotationDegrees(new Random(e.getId()).nextInt(90)-45));switch(cfg.style){case 15->blade(e,p,buffers,light);case 4->bolt(p,buffers,cfg.trail);case 12->orb(p,buffers);case 6->{p.scale(.5F,.5F,.5F);p.mulPose(Axis.ZP.rotationDegrees(90));p.mulPose(Axis.YP.rotationDegrees(90));mesh("models/projectiles/projectiles.obj","textures/models/projectiles/rocket.png","Rocket",p,buffers,light);}case 13->mesh("models/weapons/meteor.obj","textures/block/block_meteor_molten.png",null,p,buffers,LightTexture.FULL_BRIGHT);default->throw new IllegalStateException("Unported old NPC render style "+cfg.style);}p.popPose();super.render(e,yaw,partial,p,buffers,light);}
 private static void blade(EntityBulletBaseNT entity,PoseStack poses,MultiBufferSource buffers,int light){
  poses.pushPose();try{poses.mulPose(Axis.ZP.rotationDegrees(90));poses.translate(0,.5,0);poses.mulPose(Axis.XP.rotationDegrees(System.currentTimeMillis()%360));poses.translate(0,-.5,0);poses.mulPose(Axis.YP.rotationDegrees(90));poses.scale(1,2,1);
   Minecraft.getInstance().getItemRenderer().renderStatic(new net.minecraft.world.item.ItemStack(com.hbm.registry.HbmContent.item("blade_titanium")),net.minecraft.world.item.ItemDisplayContext.FIXED,light,OverlayTexture.NO_OVERLAY,poses,buffers,entity.level(),entity.getId());
  }finally{poses.popPose();}
 }
 private static WavefrontMesh model(String path){return LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:"+path));}
 private static void mesh(String path,String texture,String part,PoseStack p,MultiBufferSource buffers,int light){var out=buffers.getBuffer(RenderType.entityCutout(ResourceLocation.parse("hbm:"+texture)));if(part==null)LegacyObjRenderer.render(model(path),p,out,light,OverlayTexture.NO_OVERLAY,0xffffffff,LegacyObjRenderer.Convention.FORGE,face->true);else LegacyObjRenderer.renderOnly(model(path),p,out,light,OverlayTexture.NO_OVERLAY,0xffffffff,LegacyObjRenderer.Convention.HFR,part);}
 private static void orb(PoseStack p,MultiBufferSource buffers){p.scale(.5F,.5F,.5F);sphere(p,buffers.getBuffer(NpcBulletRenderTypes.ORB));p.scale(.75F,.75F,.75F);sphere(p,buffers.getBuffer(NpcBulletRenderTypes.ORB));p.scale(1F/.75F,1F/.75F,1F/.75F);for(int i=0;i<3;i++)spark((int)(System.currentTimeMillis()/100+100*i),p,buffers);}
 private static void sphere(PoseStack p,VertexConsumer out){var mesh=model("models/sphere_uv.obj");for(var t:mesh.triangles()){var face=mesh.faces().get(t.face());for(int c:new int[]{t.first(),t.second(),t.third(),t.third()}){var v=mesh.positions().get(face.corners().get(c).position());out.addVertex(p.last(),v.x(),v.y(),v.z()).setColor(.5F,0,0,.5F);}}}
 private static void spark(int seed,PoseStack p,MultiBufferSource buffers){var random=new Random(seed);var direction=new Vec3(random.nextDouble()-.5,random.nextDouble()-.5,random.nextDouble()-.5).normalize();double x=0,y=0,z=0;for(int i=0;i<2+random.nextInt(3);i++){double oldX=x,oldY=y,oldZ=z;var d=direction.normalize();x+=d.x*random.nextFloat();y+=d.y*random.nextFloat();z+=d.z*random.nextFloat();line(p,buffers.getBuffer(NpcBulletRenderTypes.SPARK_OUTER),oldX,oldY,oldZ,x,y,z,0xffff0000);line(p,buffers.getBuffer(NpcBulletRenderTypes.SPARK_INNER),oldX,oldY,oldZ,x,y,z,0xffff8080);}}
 private static void line(PoseStack p,VertexConsumer out,double a,double b,double c,double x,double y,double z,int color){var n=new org.joml.Vector3f((float)(x-a),(float)(y-b),(float)(z-c)).normalize();out.addVertex(p.last(),(float)a,(float)b,(float)c).setColor(color).setNormal(p.last(),n.x,n.y,n.z);out.addVertex(p.last(),(float)x,(float)y,(float)z).setColor(color).setNormal(p.last(),n.x,n.y,n.z);}
 private static void vertex(PoseStack p,VertexConsumer out,float[] v,int rgb){out.addVertex(p.last(),v[0],v[1],v[2]).setColor((rgb>>16&255)/255F,(rgb>>8&255)/255F,(rgb&255)/255F,v[3]);}
 private static void bolt(PoseStack p,MultiBufferSource buffers,int trail){int rgb=switch(trail){case 0->0x3f00bf;case 1->0xffff00;case 2->0xff0000;case 4->0x00ff00;default->throw new IllegalStateException("Unported original bolt trail "+trail);};p.pushPose();p.scale(.25F,.125F,.125F);p.scale(-1,1,1);p.scale(2,2,2);var out=buffers.getBuffer(NpcBulletRenderTypes.BOLT);for(float[][] face:BOLT){for(int i=0;i<face.length;i++)vertex(p,out,face[i],rgb);if(face.length==3)vertex(p,out,face[2],rgb);}p.popPose();}
 private static final float[][][] BOLT={
 {{6,0,0,1},{3,-1,-1,0},{3,1,-1,0}},{{3,-1,1,0},{6,0,0,1},{3,1,1,0}},{{3,-1,-1,0},{6,0,0,1},{3,-1,1,0}},{{6,0,0,1},{3,1,-1,0},{3,1,1,0}},
 {{6,0,0,1},{4,-.5F,-.5F,1},{4,.5F,-.5F,1}},{{4,-.5F,.5F,1},{6,0,0,1},{4,.5F,.5F,1}},{{4,-.5F,-.5F,1},{6,0,0,1},{4,-.5F,.5F,1}},{{6,0,0,1},{4,.5F,-.5F,1},{4,.5F,.5F,1}},
 {{4,.5F,-.5F,1},{4,.5F,.5F,1},{0,.5F,.5F,0},{0,.5F,-.5F,0}},{{4,-.5F,-.5F,1},{4,-.5F,.5F,1},{0,-.5F,.5F,0},{0,-.5F,-.5F,0}},{{4,-.5F,.5F,1},{4,.5F,.5F,1},{0,.5F,.5F,0},{0,-.5F,.5F,0}},{{4,-.5F,-.5F,1},{4,.5F,-.5F,1},{0,.5F,-.5F,0},{0,-.5F,-.5F,0}}};
}
